BEGIN TRANSACTION;
CREATE TABLE act716_species (
	id INTEGER NOT NULL, 
	family VARCHAR, 
	scientific_name VARCHAR NOT NULL, 
	local_name_ms VARCHAR, 
	common_name_en VARCHAR, 
	name_zh VARCHAR, 
	schedule VARCHAR, 
	protection_status VARCHAR, 
	verification_basis VARCHAR, 
	PRIMARY KEY (id)
);
CREATE TABLE adventures (
	id INTEGER NOT NULL, 
	parent_id INTEGER, 
	child_id INTEGER, 
	location_id VARCHAR, 
	status VARCHAR, 
	planned_at DATETIME, 
	checklist JSON, 
	PRIMARY KEY (id), 
	FOREIGN KEY(parent_id) REFERENCES users (id), 
	FOREIGN KEY(child_id) REFERENCES child_profiles (id), 
	FOREIGN KEY(location_id) REFERENCES locations (id)
);
CREATE TABLE badges (
	id INTEGER NOT NULL, 
	code VARCHAR, 
	title VARCHAR, 
	criteria VARCHAR, 
	PRIMARY KEY (id), 
	UNIQUE (code)
);
CREATE TABLE child_badges (
	id INTEGER NOT NULL, 
	child_id INTEGER, 
	badge_id INTEGER, 
	awarded_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(child_id) REFERENCES child_profiles (id), 
	FOREIGN KEY(badge_id) REFERENCES badges (id)
);
CREATE TABLE child_profiles (
	id INTEGER NOT NULL, 
	parent_user_id INTEGER NOT NULL, 
	display_name VARCHAR, 
	age_band VARCHAR, 
	xp INTEGER, 
	level INTEGER, 
	safety_briefing_done BOOLEAN, 
	learning_streak INTEGER, 
	PRIMARY KEY (id), 
	FOREIGN KEY(parent_user_id) REFERENCES users (id)
);
CREATE TABLE collection_entries (
	id INTEGER NOT NULL, 
	child_id INTEGER, 
	species_id VARCHAR, 
	unlock_reason VARCHAR, 
	observed_boolean BOOLEAN, 
	PRIMARY KEY (id), 
	FOREIGN KEY(child_id) REFERENCES child_profiles (id), 
	FOREIGN KEY(species_id) REFERENCES species (id)
);
CREATE TABLE consent_events (
	id INTEGER NOT NULL, 
	parent_id INTEGER, 
	child_id INTEGER, 
	consent_type VARCHAR, 
	value BOOLEAN, 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(parent_id) REFERENCES users (id), 
	FOREIGN KEY(child_id) REFERENCES child_profiles (id)
);
CREATE TABLE documents (
	id INTEGER NOT NULL, 
	source VARCHAR, 
	title VARCHAR, 
	content TEXT, 
	source_url VARCHAR, 
	license VARCHAR, 
	PRIMARY KEY (id)
);
CREATE TABLE historical_observations (
	id INTEGER NOT NULL, 
	species_id VARCHAR, 
	location_id VARCHAR, 
	observed_at VARCHAR, 
	source_ref VARCHAR, 
	public_precision VARCHAR, 
	PRIMARY KEY (id), 
	FOREIGN KEY(species_id) REFERENCES species (id), 
	FOREIGN KEY(location_id) REFERENCES locations (id)
);
CREATE TABLE identifications (
	id INTEGER NOT NULL, 
	child_id INTEGER, 
	image_id VARCHAR, 
	model_version VARCHAR, 
	topk_json JSON, 
	selected_species_id VARCHAR, 
	confidence FLOAT, 
	user_confirmed BOOLEAN, 
	PRIMARY KEY (id), 
	FOREIGN KEY(child_id) REFERENCES child_profiles (id), 
	FOREIGN KEY(selected_species_id) REFERENCES species (id)
);
CREATE TABLE locations (
	id VARCHAR NOT NULL, 
	name VARCHAR NOT NULL, 
	type VARCHAR, 
	lat FLOAT, 
	lng FLOAT, 
	verified BOOLEAN, 
	description TEXT, 
	facilities JSON, 
	best_time VARCHAR, 
	distance_km FLOAT, 
	why_recommended TEXT, 
	PRIMARY KEY (id)
);
CREATE TABLE parent_profiles (
	user_id INTEGER NOT NULL, 
	display_name VARCHAR, 
	privacy_preferences JSON, 
	PRIMARY KEY (user_id), 
	FOREIGN KEY(user_id) REFERENCES users (id)
);
CREATE TABLE quiz_attempts (
	id INTEGER NOT NULL, 
	child_id INTEGER, 
	quiz_id INTEGER, 
	score INTEGER, 
	xp_awarded INTEGER, 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(child_id) REFERENCES child_profiles (id), 
	FOREIGN KEY(quiz_id) REFERENCES quizzes (id)
);
CREATE TABLE quizzes (
	id INTEGER NOT NULL, 
	species_id VARCHAR, 
	version INTEGER, 
	questions_json JSON, 
	PRIMARY KEY (id), 
	FOREIGN KEY(species_id) REFERENCES species (id)
);
CREATE TABLE sightings (
	id INTEGER NOT NULL, 
	child_id INTEGER, 
	species_id VARCHAR, 
	lat_private FLOAT, 
	lng_private FLOAT, 
	public_geohash VARCHAR, 
	status VARCHAR, 
	sensitive_species BOOLEAN, 
	PRIMARY KEY (id), 
	FOREIGN KEY(child_id) REFERENCES child_profiles (id), 
	FOREIGN KEY(species_id) REFERENCES species (id)
);
CREATE TABLE species (
	id VARCHAR NOT NULL, 
	common_name VARCHAR NOT NULL, 
	scientific_name VARCHAR, 
	category VARCHAR, 
	habitat TEXT, 
	diet TEXT, 
	threats TEXT, 
	conservation_status VARCHAR, 
	fun_fact TEXT, 
	responsible_observation TEXT, 
	source_name VARCHAR, 
	source_ref VARCHAR, 
	sensitive BOOLEAN, 
	emoji VARCHAR, 
	image_url VARCHAR, 
	name_zh VARCHAR, 
	distinctive_features TEXT, 
	habitat_zh TEXT, 
	diet_zh TEXT, 
	threats_zh TEXT, 
	fun_fact_zh TEXT, 
	responsible_zh TEXT, 
	act716_schedule VARCHAR, 
	act716_status VARCHAR, 
	PRIMARY KEY (id)
);
CREATE TABLE species_images (
	id INTEGER NOT NULL, 
	species_id VARCHAR, 
	uri VARCHAR, 
	licence VARCHAR, 
	attribution VARCHAR, 
	PRIMARY KEY (id), 
	FOREIGN KEY(species_id) REFERENCES species (id)
);
CREATE TABLE users (
	id INTEGER NOT NULL, 
	role VARCHAR NOT NULL, 
	created_at DATETIME, 
	PRIMARY KEY (id)
);
COMMIT;
